using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class UnitDirectiveHoldingTests
{
 static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
 static NewMilitaryInput Input(WorldSession s,NewMilitaryAction action)=>new(new("request:unit-recipient/"+s.Revision+"/"+action),action);
 static void Send(WorldSession s,NewMilitaryAction action,long amount=0){var result=s.DecideNewMilitary(Input(s,action) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);}
 static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
 static WorldSession Away(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{ObservationPolicy=NewGameMilitary.ObservationContract},s.PlayerControl,s.Revision).Code);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+90000,a.Y-10000),B=new(a.X+90000,a.Y+10000)},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Max(l=>l.EndAt)+1);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Max(l=>l.EndAt)+1);return s;}
 static NewMilitaryInput Query(WorldSession s,int unit)=>Input(s,NewMilitaryAction.InquireUnitKnown) with{InquiryTarget=new(NewGameMilitary.UnitRecipientContract,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[unit])!),PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};
 static TroopDispatch Dispatch(WorldSession s,int unit){var i=Query(s,unit);var r=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();}
 static UnitPostInquiryAnswer Answer(ContractWorld w,TroopReceipt receipt)=>ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==receipt.ReplyMessage).Body));

 static NewMilitaryInput Directive(WorldSession s,int unit,UnitDirectiveKind kind){var w=s.DiagnosticSnapshot();var k=NewGameMilitary.SelectKnownTarget(w,NewGameMilitary.UnitIds[unit])!;return Input(s,NewMilitaryAction.SendUnitDirective) with{Directive=new(NewGameMilitary.UnitDirectiveContract,k,kind,kind==UnitDirectiveKind.Move?new(k.Position.X+8000,k.Position.Y):null),DeliverBy=s.Seconds+600,PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract,OriginalPolicy=NewGameMilitary.UnitDirectiveHoldingContract};}

 static TroopDispatch FailedOriginal(WorldSession s,bool learn=true,int index=1,UnitDirectiveKind kind=UnitDirectiveKind.Move,bool holding=true){Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);var i=Directive(s,index,kind) with{OriginalPolicy=holding?NewGameMilitary.UnitDirectiveHoldingContract:null};Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var root=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();At(s,root.DueAt);var r=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Receipts.Last();Assert.False(r.Delivered);if(learn)At(s,r.ReplyDueAt);return root;}
 static void HomeUnits(WorldSession s){long end=s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max();At(s,Math.Max(s.Seconds,end+2));}
 static NewMilitaryInput Retry(WorldSession s,TroopDispatch root)=>Input(s,NewMilitaryAction.RetryUnitDirective) with{DirectiveRetry=new(NewGameMilitary.UnitDirectiveRetryContract,root.Id,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),root.Recipient)!),TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};

 static UnitHeldTransfer Handoff(WorldSession s,TroopDispatch root){var paper=NewGameMilitary.SelectDirectivePaper(s.DiagnosticSnapshot(),root.Id);Assert.NotNull(paper);var input=Input(s,NewMilitaryAction.DeliverHeldUnitDirective) with{DirectiveHandoff=paper};var result=s.DecideNewMilitary(input,s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();}
 [Fact]public void RetainedOriginalHasPhysicalHolderAndLateMoveWithSameRestoredFuture(){var s=Away();var root=FailedOriginal(s);HomeUnits(s);var w=s.DiagnosticSnapshot();var paper=NewGameMilitary.SelectDirectivePaper(w,root.Id);Assert.NotNull(paper);Assert.Contains(NewGameMilitary.HeldPapers(w,s.Seconds),h=>h.Message==root.Message&&h.Attempt==root.Attempt&&h.Holder==paper.Carrier);var initial=w.NewMilitary!.UnitDirective!.Receipts.Single(r=>r.Id==root.Id);Assert.False(initial.Delivered);var t=Handoff(s,root);Assert.Equal(root.Attempt,t.Attempt);Assert.Contains(root.Attempt,t.Cargo);At(s,t.DueAt-1);var restored=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,restored})At(v,t.DueAt);w=s.DiagnosticSnapshot();var effect=w.NewMilitary!.UnitDirective!.Holding!.Outcomes.Single();Assert.True(effect.Received);Assert.Contains(NewGameMilitary.CourierFrames(w,s.Seconds),f=>f.Carrier==effect.Carrier&&f.Position==effect.Origin);Assert.Equal(UnitDirectiveOutcome.Applied,effect.Outcome);Assert.NotNull(effect.Order);Assert.False(w.NewMilitary.UnitDirective.Receipts.Single(r=>r.Id==root.Id).Delivered);Assert.Empty(w.NewMilitary.UnitDirective.Effects);Assert.Single(w.Messaging.Receipts,r=>r.MessageId==root.Message);Assert.Single(w.NewMilitary.Orders,o=>o.Id==effect.Order);Assert.Equal(new[]{1},w.NewMilitary.Orders.Single(o=>o.Id==effect.Order).AffectedUnits);Assert.False(MessageFlow.Knows(w.Messaging,effect.ReplyMessage!,w.PlayerControl.Value));foreach(var v in new[]{s,restored})At(v,effect.DueAt);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));w=s.DiagnosticSnapshot();Assert.True(MessageFlow.Knows(w.Messaging,effect.ReplyMessage!,w.PlayerControl.Value));Assert.Contains("遅着返書",NewGameMilitary.UnitDirectiveStatus(w));Assert.True(NewGameMilitary.ReceiptConfirmedToSender(w,root.Message,w.PlayerControl.Value));new WorldSession(w);}

 static void PersonOffCamp(WorldSession s){var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(a.X-20000,a.Y)},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max()+1);}
 [Theory][InlineData(0,0)][InlineData(0,1)][InlineData(0,2)][InlineData(1,0)][InlineData(1,1)][InlineData(1,2)][InlineData(2,0)][InlineData(2,1)][InlineData(2,2)]public void RealOriginalAndCopyExecuteOneRootRegardlessOfArrivalOrder(int ordering,int index){var s=Away();PersonOffCamp(s);var root=FailedOriginal(s,true,index,UnitDirectiveKind.Hold);HomeUnits(s);UnitHeldTransfer t;TroopDispatch copy;
 if(ordering==0){Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Retry(s,root),s.PlayerControl,s.Revision).Code);copy=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();At(s,copy.DueAt);t=Handoff(s,root);Assert.True(copy.DueAt<t.DueAt);}
 else if(ordering==1){t=Handoff(s,root);At(s,s.Seconds+1);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Retry(s,root),s.PlayerControl,s.Revision).Code);copy=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();Assert.True(t.DueAt<copy.DueAt);At(s,t.DueAt);}
 else{Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Retry(s,root),s.PlayerControl,s.Revision).Code);copy=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();t=Handoff(s,root);Assert.Equal(copy.DueAt,t.DueAt);At(s,t.DueAt-1);}
 var restored=new WorldSession(s.DiagnosticSnapshot());long at=Math.Max(copy.DueAt,t.DueAt);foreach(var v in new[]{s,restored})At(v,Math.Max(v.Seconds,at));var w=s.DiagnosticSnapshot();var state=w.NewMilitary!.UnitDirective!;var late=state.Holding!.Outcomes.Single();Assert.True(late.Received);Assert.True(state.Receipts.Single(r=>r.Id==copy.Id).Delivered);Assert.Single(w.Messaging.Receipts,r=>r.MessageId==root.Message);Assert.Equal(1,state.Effects.Count(e=>e.Outcome==UnitDirectiveOutcome.Applied)+state.Holding.Outcomes.Count(e=>e.Outcome==UnitDirectiveOutcome.Applied));Assert.Single(w.NewMilitary.Orders,o=>o.Action==NewMilitaryAction.SendUnitDirective);Assert.Equal(ordering==1?UnitDirectiveOutcome.Applied:UnitDirectiveOutcome.AlreadyApplied,late.Outcome);Assert.Equal(ordering==1?UnitDirectiveOutcome.AlreadyApplied:UnitDirectiveOutcome.Applied,state.Effects.Single().Outcome);long replies=Math.Max(late.DueAt,state.Receipts.Single(r=>r.Id==copy.Id).ReplyDueAt);foreach(var v in new[]{s,restored})At(v,Math.Max(v.Seconds,replies+1));Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));new WorldSession(s.DiagnosticSnapshot());}

 [Fact]public void LegacyUnretainedOriginalNeverCreatesAPaper(){var s=Away();var root=FailedOriginal(s,true,1,UnitDirectiveKind.Move,false);HomeUnits(s);Assert.Null(s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Holding);Assert.Null(NewGameMilitary.SelectDirectivePaper(s.DiagnosticSnapshot(),root.Id));Assert.DoesNotContain(NewGameMilitary.HeldPapers(s.DiagnosticSnapshot(),s.Seconds),h=>h.Message==root.Message);new WorldSession(s.DiagnosticSnapshot());}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]public void ForgedPhysicalPaperReferenceIsAtomic(int kind){var s=Away();var root=FailedOriginal(s);HomeUnits(s);var paper=NewGameMilitary.SelectDirectivePaper(s.DiagnosticSnapshot(),root.Id)!;paper=kind switch{0=>paper with{Contract="unknown"},1=>paper with{Carrier=new("courier:unrelated")},2=>paper with{Attempt="attempt:unrelated/1"},3=>paper with{Known=paper.Known with{Position=new(paper.Known.Position.X+1,paper.Known.Position.Y)}},4=>paper with{Known=paper.Known with{Unit=NewGameMilitary.UnitIds[2]}},_=>paper with{Original=new("request:unrelated")}};string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.DeliverHeldUnitDirective) with{DirectiveHandoff=paper},s.PlayerControl,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
 [Fact]public void BusyCarrierCannotCarryTheSamePaperAgain(){var s=Away();var root=FailedOriginal(s);HomeUnits(s);var paper=NewGameMilitary.SelectDirectivePaper(s.DiagnosticSnapshot(),root.Id)!;var input=Input(s,NewMilitaryAction.DeliverHeldUnitDirective) with{DirectiveHandoff=paper};Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Null(NewGameMilitary.SelectDirectivePaper(s.DiagnosticSnapshot(),root.Id));Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(input,s.PlayerControl,0).Code);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(input with{Id=new("request:another-handoff")},s.PlayerControl,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
 [Fact]public void ExpiredPhysicalOriginalCannotBeHandedOver(){var s=Away();var root=FailedOriginal(s);HomeUnits(s);var paper=NewGameMilitary.SelectDirectivePaper(s.DiagnosticSnapshot(),root.Id)!;var until=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==root.Message).DeliverBy!.Value;At(s,until);Assert.Null(NewGameMilitary.SelectDirectivePaper(s.DiagnosticSnapshot(),root.Id));paper=paper with{Known=NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),root.Recipient)!};string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.DeliverHeldUnitDirective) with{DirectiveHandoff=paper},s.PlayerControl,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
 [Fact]public void LateUnexecutedOriginalDoesNotOverrideNewerHold(){var s=Away();var root=FailedOriginal(s);HomeUnits(s);var hold=Directive(s,1,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(hold,s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last().DueAt);var before=ContractJson.CanonicalHash(s.DiagnosticSnapshot().NewMilitary!.Orders);var t=Handoff(s,root);At(s,t.DueAt);var w=s.DiagnosticSnapshot();Assert.Equal(UnitDirectiveOutcome.Superseded,w.NewMilitary!.UnitDirective!.Holding!.Outcomes.Single().Outcome);Assert.Equal(before,ContractJson.CanonicalHash(w.NewMilitary.Orders));new WorldSession(w);}
 [Fact]public void LostLateAckIsActualPaperRecoveredByTakeHeldReply(){var s=Away();PersonOffCamp(s);var root=FailedOriginal(s,true,1,UnitDirectiveKind.Hold);HomeUnits(s);var t=Handoff(s,root);At(s,t.DueAt);var f=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Holding!.Outcomes.Single();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(a.X-40000,a.Y)},s.PlayerControl,s.Revision).Code);At(s,f.DueAt);var w=s.DiagnosticSnapshot();Assert.False(MessageFlow.Knows(w.Messaging,f.ReplyMessage!,w.PlayerControl.Value));Assert.Contains(NewGameMilitary.HeldPapers(w,s.Seconds),h=>h.Message==f.ReplyMessage&&h.Holder==t.Carrier);long end=w.NewMilitary!.Withdrawal!.Journeys.Last().Route.Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max();At(s,Math.Max(s.Seconds,end+1));Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=f.Destination},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max()+1);Assert.True(NewGameMilitary.HeldAllowed(s.DiagnosticSnapshot(),NewMilitaryAction.TakeHeldReply));Send(s,NewMilitaryAction.TakeHeldReply);var take=s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();Assert.Equal(f.ReplyMessage,take.Message);var restored=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,restored})At(v,take.DueAt);w=s.DiagnosticSnapshot();Assert.True(MessageFlow.Knows(w.Messaging,f.ReplyMessage!,w.PlayerControl.Value));Assert.Contains("遅着返書",NewGameMilitary.UnitDirectiveStatus(w));Assert.True(NewGameMilitary.ReceiptConfirmedToSender(w,root.Message,w.PlayerControl.Value));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));new WorldSession(w);}
 [Fact]public void MissingPostRejectsLateOriginalWithoutFollowingItsActualPosition(){var s=Away();PersonOffCamp(s);var root=FailedOriginal(s);HomeUnits(s);var move=Directive(s,1,UnitDirectiveKind.Move);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(move,s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last().DueAt);var t=Handoff(s,root);var destination=t.Destination;At(s,t.DueAt);var w=s.DiagnosticSnapshot();Assert.False(w.NewMilitary!.UnitDirective!.Holding!.Outcomes.Single().Received);Assert.NotEqual(destination,NewGameMilitary.Position(w,1,s.Seconds));Assert.Equal(destination,w.NewMilitary.HeldDelivery!.Transfers.Last().Destination);Assert.Null(w.NewMilitary.UnitDirective.Holding.Outcomes.Single().ReplyMessage);new WorldSession(w);}
 [Fact]public void ReturningCommandBeforeLateArrivalCannotReacquireIt(){var s=Away();var root=FailedOriginal(s,true,1,UnitDirectiveKind.Hold);HomeUnits(s);var t=Handoff(s,root);Send(s,NewMilitaryAction.Attach);Send(s,NewMilitaryAction.Enter);Send(s,NewMilitaryAction.Unload,s.DiagnosticSnapshot().NewMilitary!.Moves.Sum(m=>m.Loading?m.Amount:-m.Amount)-s.DiagnosticSnapshot().NewMilitary!.Uses.Sum(u=>u.Consumed));Send(s,NewMilitaryAction.Report);Send(s,NewMilitaryAction.Return);At(s,s.Seconds+3);Assert.Contains(s.DiagnosticSnapshot().NewMilitary!.Events,e=>e.Effect==MilitaryEffect.Returned);Assert.All(s.DiagnosticSnapshot().Units,u=>Assert.Equal(s.DiagnosticSnapshot().NewMilitary!.Terms.Principal,u.Commander));At(s,Math.Max(s.Seconds,t.DueAt));var w=s.DiagnosticSnapshot();Assert.False(w.NewMilitary!.UnitDirective!.Holding!.Outcomes.Single().Received,"late receive at"+t.DueAt+" events="+System.Text.Encoding.UTF8.GetString(ContractJson.Write(w.NewMilitary.Events)));Assert.Empty(w.NewMilitary.UnitDirective.Effects);Assert.All(w.Units,u=>Assert.Equal(w.NewMilitary.Terms.Principal,u.Commander));Assert.True(NewGameMilitary.View(w).Custody);new WorldSession(w);}
 [Fact]public void SavedRetainedHolderTamperingIsRejected(){var s=Away();var root=FailedOriginal(s);HomeUnits(s);var w=s.DiagnosticSnapshot();var x=w.NewMilitary!.UnitDirective!.Holding!;x.Holdings[0]=x.Holdings[0] with{Holder=new("courier:forged-holder")};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
}
